def get_prime_factors(k):
    factors = set()
    d = 2
    temp = k
    while d * d <= temp:
        if temp % d == 0:
            factors.add(d)
            while temp % d == 0:
                temp //= d
        d += 1
    if temp > 1:
        factors.add(temp)
    return factors

def D(n):
    return n**3 + 4*n**2 + 6*n + 4

print("n | D(n) | Prime Factors | Has factor p > 5?")
print("-" * 50)
for n in range(11):
    d_n = D(n)
    factors = get_prime_factors(d_n)
    has_p_gt_5 = any(p > 5 for p in factors)
    print(f"{n} | {d_n} | {sorted(list(factors))} | {has_p_gt_5}")

