def check_2_5_form(m):
    if m <= 0:
        return False
    temp = m
    if temp % 2 == 0:
        while temp % 2 == 0:
            temp //= 2

    if temp % 5 == 0:
        while temp % 5 == 0:
            temp //= 5

    return temp == 1

# Test k up to 100 (n up to 99)
max_k = 100
solutions_k = []
for k in range(1, max_k + 1):
    M = k*k + 1
    if check_2_5_form(M):
        solutions_k.append(k)

print(f"Found k values (n+1) such that (n+1)^2 + 1 is of the form 2^x 5^y: {solutions_k}")
